    protected function resetMessageCatalog()
    {
        $this->messageCatalogEntries = [];
        $this->messageCatalogFormat = ':message';
        $this->messageKeyIndex = [];
        $this->formattedMessageBuffer = [];
        $this->wildcardMessageBuffer = [];

        return $this;
    }

    protected function formatCatalogPlaceholder($message, $format, $messageKey)
    {
        $this->formattedMessageBuffer[] = $message;

        return str_replace([':message', ':key'], [$message, $messageKey], $format);
    }

    protected function matchCatalogWildcardKey($pattern, $messageKey)
    {
        $this->wildcardMessageBuffer['pattern'] = $pattern;
        $this->wildcardMessageBuffer['candidate'] = $messageKey;

        if ($pattern === $messageKey) {
            return true;
        }

